// supply half: owns the reactive state
val query: Var[String] = Var("")

// presentational half: signals in, events out, no state of its own
def searchInput: HtmlElement =
  input(typ := "text", value <-- query, onInput --> query)

val page: HtmlElement =
  div(h1("Search"), searchInput, ul(children <-- results(query.signal)))
